window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a79bda4ecb44417f"]={"versions": [{"id": "FIG-a79bda4ecb44417f", "releases": ["R4.1.3", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Metamodell- bzw. Konzeptdiagramm aus der Spezifikation AUTOSAR Timing Extensions (TPS TimingExtensions). Das Diagramm veranschaulicht das Modellierungsprinzip eines gewöhnlichen Ausführungsreihenfolge-Constraints (Ordinary Execution Order Constraint) im Kontext der zeitlichen Ablaufsteuerung und Ausführungsordnung von Software-Funktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei zentrale Modellklassen und deren Instanzbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>EOC (Execution Order Constraint)</strong>: Übergeordnetes Container- bzw. Constraint-Element.</li>\n<li><strong>EOCEER (Execution Order Constraint Executable Entity Reference)</strong>: Referenzelement zur Einbindung einer ausführbaren Entität in die Kette. EOC aggregiert mehrere EOCEER über eine Kompositionsbeziehung (ausgefüllte Raute am EOC).</li>\n<li><strong>successor</strong>: Gerichtete Assoziation zwischen aufeinanderfolgenden EOCEER-Instanzen, die eine lineare Sequenz bildet.</li>\n<li><strong>Executable Entity</strong>: Zielentität, auf die jedes EOCEER über eine unidirektionale Pfeilreferenz verweist.</li>\n<li><strong>Legend</strong>: Textuelle Legende mit den Abkürzungen EOC (<em>Execution Order Constraint</em>) und EER (<em>Executable Entity Reference</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine strikte sequentielle Ablaufkette. Die vier dargestellten EOCEER-Knoten sind über gerichtete <code>successor</code>-Relationen von links nach rechts verkettet:</p>\n<ol class=\"fig-list\">\n<li>Das erste EOCEER referenziert die erste Executable Entity.</li>\n<li>Über die <code>successor</code>-Kante wird das zweite EOCEER als Nachfolger bestimmt, welches auf die zweite Executable Entity verweist.</li>\n<li>Dieser Ablauf setzt sich linear über das dritte bis zum vierten EOCEER fort.</li>\n</ol>\n<p class=\"fig-p\">Die Ausführung der referenzierten Executable Entities muss somit in genau dieser festgelegten Reihenfolge erfolgen, wobei die Gesamtheit der Knoten durch das übergeordnete EOC gekapselt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das semantische Grundmuster für gewöhnliche Execution Order Constraints im AUTOSAR-Timing-Modell. Für Entwickler und Timing-Analysetools bedeutet dies, dass bei der Ablaufplanung (Scheduling, z. B. im RTE- oder OS-Kontext) die über <code>successor</code> vorgegebene Reihenfolge der referenzierten Executable Entities zwingend einzuhalten ist. Es dürfen keine zyklischen Abhängigkeiten innerhalb einer solchen einfachen Kette auftreten.</p>"}, {"id": "FIG-d2c76ebe89dedaf0", "releases": ["R4.2.2", "R4.3.1", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Metamodell- bzw. Konzeptdiagramm aus der Spezifikation AUTOSAR Timing Extensions (TPS TimingExtensions). Das Diagramm veranschaulicht das Modellierungsprinzip eines gewöhnlichen Ausführungsreihenfolge-Constraints (Ordinary Execution Order Constraint) im Kontext der zeitlichen Ablaufsteuerung und Ausführungsordnung von Software-Funktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei zentrale Modellklassen und deren Instanzbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>EOC (Execution Order Constraint)</strong>: Übergeordnetes Container- bzw. Constraint-Element.</li>\n<li><strong>EOCEER (Execution Order Constraint Executable Entity Reference)</strong>: Referenzelement zur Einbindung einer ausführbaren Entität in die Kette. EOC aggregiert mehrere EOCEER über eine Kompositionsbeziehung (ausgefüllte Raute am EOC).</li>\n<li><strong>successor</strong>: Gerichtete Assoziation zwischen aufeinanderfolgenden EOCEER-Instanzen, die eine lineare Sequenz bildet.</li>\n<li><strong>Executable Entity</strong>: Zielentität, auf die jedes EOCEER über eine unidirektionale Pfeilreferenz verweist.</li>\n<li><strong>Legend</strong>: Textuelle Legende mit den Abkürzungen EOC (<em>Execution Order Constraint</em>) und EER (<em>Executable Entity Reference</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine strikte sequentielle Ablaufkette. Die vier dargestellten EOCEER-Knoten sind über gerichtete <code>successor</code>-Relationen von links nach rechts verkettet:</p>\n<ol class=\"fig-list\">\n<li>Das erste EOCEER referenziert die erste Executable Entity.</li>\n<li>Über die <code>successor</code>-Kante wird das zweite EOCEER als Nachfolger bestimmt, welches auf die zweite Executable Entity verweist.</li>\n<li>Dieser Ablauf setzt sich linear über das dritte bis zum vierten EOCEER fort.</li>\n</ol>\n<p class=\"fig-p\">Die Ausführung der referenzierten Executable Entities muss somit in genau dieser festgelegten Reihenfolge erfolgen, wobei die Gesamtheit der Knoten durch das übergeordnete EOC gekapselt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das semantische Grundmuster für gewöhnliche Execution Order Constraints im AUTOSAR-Timing-Modell. Für Entwickler und Timing-Analysetools bedeutet dies, dass bei der Ablaufplanung (Scheduling, z. B. im RTE- oder OS-Kontext) die über <code>successor</code> vorgegebene Reihenfolge der referenzierten Executable Entities zwingend einzuhalten ist. Es dürfen keine zyklischen Abhängigkeiten innerhalb einer solchen einfachen Kette auftreten.</p>"}, {"id": "FIG-7af12e53e0c6448b", "releases": ["R18-10_R4.4.0_R1.5.0", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Metamodell- bzw. Konzeptdiagramm aus der Spezifikation AUTOSAR Timing Extensions (TPS TimingExtensions). Das Diagramm veranschaulicht das Modellierungsprinzip eines gewöhnlichen Ausführungsreihenfolge-Constraints (Ordinary Execution Order Constraint) im Kontext der zeitlichen Ablaufsteuerung und Ausführungsordnung von Software-Funktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei zentrale Modellklassen und deren Instanzbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>EOC (Execution Order Constraint)</strong>: Übergeordnetes Container- bzw. Constraint-Element.</li>\n<li><strong>EOCEER (Execution Order Constraint Executable Entity Reference)</strong>: Referenzelement zur Einbindung einer ausführbaren Entität in die Kette. EOC aggregiert mehrere EOCEER über eine Kompositionsbeziehung (ausgefüllte Raute am EOC).</li>\n<li><strong>successor</strong>: Gerichtete Assoziation zwischen aufeinanderfolgenden EOCEER-Instanzen, die eine lineare Sequenz bildet.</li>\n<li><strong>Executable Entity</strong>: Zielentität, auf die jedes EOCEER über eine unidirektionale Pfeilreferenz verweist.</li>\n<li><strong>Legend</strong>: Textuelle Legende mit den Abkürzungen EOC (<em>Execution Order Constraint</em>) und EER (<em>Executable Entity Reference</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine strikte sequentielle Ablaufkette. Die vier dargestellten EOCEER-Knoten sind über gerichtete <code>successor</code>-Relationen von links nach rechts verkettet:</p>\n<ol class=\"fig-list\">\n<li>Das erste EOCEER referenziert die erste Executable Entity.</li>\n<li>Über die <code>successor</code>-Kante wird das zweite EOCEER als Nachfolger bestimmt, welches auf die zweite Executable Entity verweist.</li>\n<li>Dieser Ablauf setzt sich linear über das dritte bis zum vierten EOCEER fort.</li>\n</ol>\n<p class=\"fig-p\">Die Ausführung der referenzierten Executable Entities muss somit in genau dieser festgelegten Reihenfolge erfolgen, wobei die Gesamtheit der Knoten durch das übergeordnete EOC gekapselt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das semantische Grundmuster für gewöhnliche Execution Order Constraints im AUTOSAR-Timing-Modell. Für Entwickler und Timing-Analysetools bedeutet dies, dass bei der Ablaufplanung (Scheduling, z. B. im RTE- oder OS-Kontext) die über <code>successor</code> vorgegebene Reihenfolge der referenzierten Executable Entities zwingend einzuhalten ist. Es dürfen keine zyklischen Abhängigkeiten innerhalb einer solchen einfachen Kette auftreten.</p>"}], "trans": [{"from": "FIG-a79bda4ecb44417f", "to": "FIG-d2c76ebe89dedaf0", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d2c76ebe89dedaf0", "to": "FIG-7af12e53e0c6448b", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7af12e53e0c6448b", "to": "FIG-d2c76ebe89dedaf0", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7af12e53e0c6448b", "to": "FIG-a79bda4ecb44417f", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
